head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf10901";

// [A] 초기 목록 미해결 — jldinf10901: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf10901.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_dataList_oncellclick
 * @description grd_dataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_dataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_dataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_dataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: clickRadio('${row.basIsuNm}','${row.basIsuAbbrv}','${row.basIsuEngNm}','${row.basIsuEngAbbrv}');focus_tr(this); (EL 미해석) */
        scwin.clickRadio(r["basIsuNm"], r["basIsuAbbrv"], r["basIsuEngNm"], r["basIsuEngAbbrv"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_dataList.oncellclick' });
    }
};

/**
 * @method
 * @name ipt_korNm_onkeydown
 * @description ipt_korNm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_korNm_onkeydown = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(($c.util.getKeyCode(ev))===13){ await scwin.send_form() }
        fn_engNumNotSpecCheck(selfVar);

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10901.ipt_korNm_onkeydown' }); }
};

/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.send_form()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf10901.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_winClose_onclick
 * @description btn_winClose 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_winClose_onclick = function(e){
    try {
        scwin.win_close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf10901.btn_winClose_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name send_form
 * @description send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send_form = async function () {
    let korNm = $c.util.getComponent('ipt_korNm').getValue(); if (korNm == null) { korNm = ''; }
    if (korNm === '') {
        await $c.win.alert("고유명을 입력해 주세요");
        ($c.util.getComponent('ipt_korNm') && $c.util.getComponent('ipt_korNm').setFocus ? $c.util.getComponent('ipt_korNm').setFocus() : ($c.util.getComponent('ipt_korNm') && $c.util.getComponent('ipt_korNm').focus ? $c.util.getComponent('ipt_korNm').focus() : console.warn('[sdd] focus 대상 미해결: ipt_korNm')));
        return;
    }
    const ckRadio = $('input[type=radio]:checked').length;
    if (ckRadio === 0) {
        await $c.win.alert("기준명을 선택해 주세요.");
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_korNm').getValue()) > 20) {
        await $c.win.alert("고유명을 20자 이내로 입력하세요.");
        $('#ipt_korNm').select();
        return;
    }
    scwin.chkDuple();
};

/**
 * @method
 * @name chkDuple
 * @description chk Duple 처리
 * @returns {void}
 * @hidden N
 */
scwin.chkDuple = function () {
    const form = (document.JLDINF10901 || { elements: [] });
    const url = "/stdcd/bond.do?method=searchElsdlsIsuNm";
    const isur_cd = (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["isur_cd"] && (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["isur_cd"]).getValue ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})["isur_cd"]).getValue() : (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("isur_cd") || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("isur_cd").getValue() : ''));
    const params = "isur_cd=" + isur_cd + "&isu_nm=" + $c.util.getComponent('ipt_isuNm').getValue() + "&unq_isu_nm=" + $c.util.getComponent('ipt_korNm').getValue();
    $.post(url, params, async function(obj) {
            if (obj === '') {
                let korNm = $c.util.getComponent('ipt_korNm').getValue(); if (korNm == null) { korNm = ''; }
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("v_isu_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuNm').getValue() + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("v_isu_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuAbbrNm") + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("v_isu_eng_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuEngNm').getValue() + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("v_isu_eng_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuEndAbbrNm") + korNm);
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("isu_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuNm').getValue());
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("isu_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuAbbrNm"));
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("isu_eng_nm")) || { setValue: function () {} }).setValue($c.util.getComponent('ipt_isuEngNm').getValue());
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("isu_eng_abbrv")) || { setValue: function () {} }).setValue(dma_hiddenStore.get("ipt_isuEndAbbrNm"));
                (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("std_isu_cd")) && ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("std_isu_cd")).setValue ? ((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById("std_isu_cd")).setValue(korNm) : (console.warn('[sdd] 부모 컴포넌트 미해결: ' + "std_isu_cd"), void (korNm)));
                $c.win.closePopup();
            } else {
                const jsonData = (typeof obj === "string" ? (typeof obj === "string" ? JSON.parse(obj) : obj) : obj);
                let strMsg = "표준코드 : " + jsonData.std_cd + "\n" + "종목명 : " + jsonData.isu_nm + " " + jsonData.unq_isu_nm + "\n\n";
                strMsg = "이미 등록된 종목명 입니다.";
                await $c.win.alert(strMsg);
                return false;
            }
    });
};

/**
 * @method
 * @name win_close
 * @description win close 처리
 * @returns {void}
 * @hidden N
 */
scwin.win_close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name clickRadio
 * @description click Radio 처리
 * @param {String} ipt_isuNm ipt_isuNm
 * @param {String} ipt_isuAbbrNm ipt_isuAbbrNm
 * @param {String} ipt_isuEngNm ipt_isuEngNm
 * @param {String} ipt_isuEndAbbrNm ipt_isuEndAbbrNm
 * @returns {void}
 * @hidden N
 */
scwin.clickRadio = function (ipt_isuNm, ipt_isuAbbrNm, ipt_isuEngNm, ipt_isuEndAbbrNm) {
    $c.util.getComponent('ipt_isuNm').setValue(ipt_isuNm);
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isuAbbrNm', ipt_isuAbbrNm) : console.warn('[sdd] hiddenStore 부재: ipt_isuAbbrNm'));
    $c.util.getComponent('ipt_isuEngNm').setValue(ipt_isuEngNm);
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isuEndAbbrNm', ipt_isuEndAbbrNm) : console.warn('[sdd] hiddenStore 부재: ipt_isuEndAbbrNm'));
};

/**
 * @method
 * @name focus_tr
 * @description focus tr 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.focus_tr = function (obj) {
    const radio = document.getElementsByName("ipt_isuList");
    let i;
    const tabNum = obj.parentNode.children.length;
    for (i = 0; i < tabNum; i++) {
        obj.parentNode.children[i].className = '';
        radio[i].checked = false;
    }
    obj.className = 'on';
    radio[obj.rowIndex -1].checked = true;
};
